# Generated by Claude ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
param(
    [string]$ListFile = "documentedFiles.txt",
    [string]$OutDir   = "./docs"
)

# Read the whitelist, skipping blank lines and comments
$files = Get-Content $ListFile |
    ForEach-Object { $_.Trim() } |
    Where-Object { $_ -and -not $_.StartsWith("#") }

# Fail early if any listed file doesn't exist
$missing = $files | Where-Object { -not (Test-Path $_) }
if ($missing) {
    Write-Error "These files were not found:`n$($missing -join "`n")"
    exit 1
}

pdoc @files --docformat google -o $OutDir
